select 'paris-pavillon-ledoyen-4889d9','A tasting menu the city is proud of','Recognised by the Michelin Guide — the address is the secret.','Pavillon Ledoyen','Pavillon Ledoyen. Recognised with: Michelin star (per Wikidata — check the current guide before booking). In Paris.',48.86608333,2.31641667,48.87,2.32,'Paris','Pavillon Ledoyen','http://www.yannick-alleno.com/','Book ahead — tables go weeks in advance.','https://maps.apple.com/?ll=48.86608333,2.31641667','https://www.google.com/maps/search/?api=1&query=48.86608333,2.31641667',(select id from public.countries where slug='france'),(select id from public.cities where slug='paris' and country_id=(select id from public.countries where slug='france')),(select id from public.categories where slug='food_drink'),'paid',499,null,(select case when exists (select 1 from public.places where city_id=(select id from public.cities where slug='paris' and country_id=(select id from public.countries where slug='france')) and status='published') then 'published' else 'draft' end),15,'walk','evening','all year',120,'medium',4,'good','wikidata','Q3427911','Q3427911','https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Pavillon_Ledoyen%2C_Paris_29_April_2017_01.jpg/1280px-Pavillon_Ledoyen%2C_Paris_29_April_2017_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Guilhem Vellut from Paris, France · CC BY 2.0 · Wikimedia Commons','{michelin_star}'::text[]
where exists (select 1 from public.cities where slug='paris' and country_id=(select id from public.countries where slug='france'))
on conflict (slug) do nothing;
